// @vegastack context-panel@0.136.3 sha256-NaMvXy5d1ETdXGr5pLH2yRvmkhaALU6xl+vlcvrVg1M=

"use client";

import * as React from "react";
import { cn } from "@vegastack/design";

import { Button } from "@/components/ui/button";
import { TextSpinner } from "@/components/ui/text-spinner";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/* ------------------------------------------------------------------------------------------------
 * ContextPanel — what fills a chat's context window, adding up to it: "26% used  25.9k /
 * 200k", one segmented bar, and a legend (swatch, label, tokens, share) in tabular columns that ends
 * with what's left. Then where the conversation auto-compacts, and Continue in a new chat for whoever may
 * send.
 * It is the body of `ContextRing`'s hover panel and of a phone's Context sheet. `variant="panel"`
 * is the record side panel's compact form: one line ("9% · 37.5k / 400k"), the bar, and the parts as
 * rows (swatch · label · tokens) with each share and the compaction note in tooltips; the host puts
 * its action in the section header. Tokens and shares only, never money.
 * ----------------------------------------------------------------------------------------------*/

/** One part of what fills the window: "Conversation", 6,900 tokens. */
export interface ContextPart {
  /** A stable key. */
  id: string;
  /** What it is: "Instructions and tools", "Memory", "Conversation", "Tool results". */
  label: React.ReactNode;
  /** Its size, in tokens. */
  tokens: number;
}

/** The panel's words. */
export interface ContextPanelLabels {
  /** The title. @default "Context" */
  title?: string;
  /** The share line. @default (percent) => `${percent}% used` */
  used?: (percent: number) => string;
  /** Measured tokens the parts don't name. @default "Other" */
  other?: string;
  /** What's left of the window. @default "Left" */
  free?: string;
  /** The note under the legend. @default (percent) => `Auto-compacts at ${percent}%` */
  threshold?: (percent: number) => string;
  /** The button. @default "Continue in a new chat" */
  summarize?: string;
  /** The button while its action runs. @default "Starting" */
  summarizing?: string;
  /** Before the chat's first answer. @default "Measured after the first answer." */
  empty?: string;
}

/** Props accepted by `ContextPanel`. */
export interface ContextPanelProps extends Omit<
  React.ComponentPropsWithRef<"div">,
  "children"
> {
  /** Tokens the last request carried; `null` before the chat's first answer. */
  used: number | null;
  /** The chat's working window, in tokens (the model it runs on decides it). */
  window: number;
  /** Where the conversation auto-compacts, as a share of the window (0–1). @default 0.9 */
  threshold?: number;
  /** What fills the window, in order; any measured remainder lists as Other. @default [] */
  parts?: readonly ContextPart[];
  /**
   * The panel's action (Continue in a new chat). Without it there is no button (a reader who can't
   * send). A returned promise keeps the button busy until it settles.
   * @default undefined
   */
  onSummarize?: () => void | Promise<unknown>;
  /** The action is under way (the host's state, a live one included). @default false */
  summarizing?: boolean;
  /** Words for a token count. @default compact: 25.9k, 1.2M */
  formatTokens?: (tokens: number) => string;
  /** The panel's words. @default undefined */
  labels?: ContextPanelLabels;
  /**
   * `default` — the hover panel: title, "26% used", the bar, a legend with shares, the note and
   * Continue in a new chat. `panel` — a side panel's Details: one line "9% · 37.5k / 400k" (the note
   * in its tooltip), the bar and compact rows (swatch · label · tokens, the share in a tooltip, Left
   * muted last). No title and no button: put the action in the section header (`onSummarize` is
   * ignored).
   * @default "default"
   */
  variant?: "default" | "panel";
}

const compact = new Intl.NumberFormat("en", {
  notation: "compact",
  maximumFractionDigits: 1,
});
/** Tokens as the panel says them: 25.9k, 200k, 1M. */
export const formatContextTokens = (tokens: number) =>
  compact.format(tokens).replace("K", "k");

/** One swatch per part, in order, from the chart set; what's left is a hollow swatch. */
const SWATCHES = [
  "bg-chart-1",
  "bg-chart-2",
  "bg-chart-3",
  "bg-chart-4",
  "bg-chart-5",
  "bg-chart-6",
] as const;

/**
 * The one measured total a ring and its panel both show: the measure, or the parts when they say
 * more, never past the window; null before the first answer.
 */
export function contextTotal(
  used: number | null,
  windowTokens: number,
  parts: readonly ContextPart[] = [],
): number | null {
  if (used === null || windowTokens <= 0) return null;
  const named = parts.reduce((sum, part) => sum + Math.max(0, part.tokens), 0);
  return Math.min(windowTokens, Math.max(0, used, named));
}

const share = (tokens: number, of: number) =>
  of > 0 ? `${((tokens / of) * 100).toFixed(1)}%` : "0.0%";

/**
 * `ContextPanel` — a chat's context, adding up to its window: the share used, one segmented bar, the
 * parts with tokens and shares, what's left, where it auto-compacts and Continue in a new chat.
 *
 * @example
 * <ContextPanel
 *   used={25_900}
 *   window={200_000}
 *   parts={[
 *     { id: "instructions", label: "Instructions and tools", tokens: 15_700 },
 *     { id: "memory", label: "Memory", tokens: 2_100 },
 *     { id: "conversation", label: "Conversation", tokens: 6_900 },
 *     { id: "tools", label: "Tool results", tokens: 1_200 },
 *   ]}
 *   onSummarize={summarize}
 * />
 */
export function ContextPanel({
  used,
  window: windowTokens,
  threshold = 0.9,
  parts = [],
  onSummarize,
  summarizing = false,
  formatTokens = formatContextTokens,
  labels,
  variant = "default",
  className,
  ...props
}: ContextPanelProps) {
  const [pending, setPending] = React.useState(false);
  const busy = summarizing || pending;
  const summarize = () => {
    const result = onSummarize?.();
    if (!result || typeof result.then !== "function") return;
    setPending(true);
    void Promise.resolve(result)
      .catch(() => undefined)
      .finally(() => setPending(false));
  };

  const measured = used !== null && windowTokens > 0;
  // One authoritative total, shared with the ring.
  const total = contextTotal(used, windowTokens, parts) ?? 0;
  const percent = measured ? Math.round((total / windowTokens) * 100) : null;
  // The legend always adds up to the window: parts fill the total in order (clipped at it), what
  // they don't name is Other, and Left is the rest.
  const rows: { id: string; label: React.ReactNode; tokens: number }[] = [];
  if (measured) {
    let left = total;
    for (const part of parts) {
      const tokens = Math.min(Math.max(0, part.tokens), left);
      left -= tokens;
      rows.push({ id: part.id, label: part.label, tokens });
    }
    if (left > 0)
      rows.push({ id: "other", label: labels?.other ?? "Other", tokens: left });
  }
  const free = measured ? windowTokens - total : 0;
  const thresholdPercent = Math.round(threshold * 100);
  const note =
    labels?.threshold?.(thresholdPercent) ??
    `Auto-compacts at ${thresholdPercent}%`;

  if (variant === "panel")
    return (
      <div
        data-slot="context-panel"
        data-variant="panel"
        className={cn("flex min-w-0 flex-col gap-2 text-sm", className)}
        {...props}
      >
        {measured ? (
          <>
            <Tooltip>
              <TooltipTrigger
                render={
                  <p
                    tabIndex={0}
                    data-slot="context-panel-used"
                    className="inline-flex min-h-6 items-center gap-1 self-start tabular-nums outline-none"
                  />
                }
              >
                {percent}%{" "}
                <span className="text-muted-foreground">
                  · {formatTokens(total)} / {formatTokens(windowTokens)}
                </span>
                <span className="sr-only">. {note}</span>
              </TooltipTrigger>
              <TooltipContent>{note}</TooltipContent>
            </Tooltip>
            <ContextBar rows={rows} windowTokens={windowTokens} />
            <ul
              data-slot="context-panel-parts"
              aria-label={labels?.title ?? "Context"}
              className="-mx-2 flex min-w-0 flex-col"
            >
              {[
                ...rows.map((row, index) => ({
                  ...row,
                  swatch: SWATCHES[index % SWATCHES.length] as string,
                  free: false,
                })),
                {
                  id: "free",
                  label: labels?.free ?? "Left",
                  tokens: free,
                  swatch: "border border-muted-foreground/50",
                  free: true,
                },
              ].map((row) => (
                <li key={row.id} className="min-w-0">
                  <Tooltip>
                    <TooltipTrigger
                      render={
                        <span
                          tabIndex={0}
                          data-slot="context-panel-part"
                          data-free={row.free ? "" : undefined}
                          className={cn(
                            // A side panel's list row (RecordPanelItem): the name at 14px, at
                            // least 30px tall, the count as its muted detail.
                            "flex min-h-7.5 min-w-0 items-center gap-2 rounded-item px-2 text-sm tabular-nums outline-none",
                            row.free && "text-muted-foreground",
                          )}
                        />
                      }
                    >
                      <span
                        aria-hidden
                        className={cn(
                          "size-1.5 shrink-0 rounded-mark",
                          row.swatch,
                        )}
                      />
                      <span className="min-w-0 flex-1 truncate">
                        {row.label}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {formatTokens(row.tokens)}
                      </span>
                      <span className="sr-only">
                        , {share(row.tokens, windowTokens)}
                      </span>
                    </TooltipTrigger>
                    <TooltipContent>
                      {share(row.tokens, windowTokens)} of the window
                    </TooltipContent>
                  </Tooltip>
                </li>
              ))}
            </ul>
          </>
        ) : (
          <p className="text-sm text-muted-foreground">
            {labels?.empty ?? "Measured after the first answer."}
          </p>
        )}
      </div>
    );

  return (
    <div
      data-slot="context-panel"
      className={cn("flex min-w-0 flex-col gap-2.5 text-sm", className)}
      {...props}
    >
      <p data-slot="context-panel-title" className="font-medium">
        {labels?.title ?? "Context"}
      </p>
      {measured ? (
        <>
          <p
            data-slot="context-panel-used"
            className="flex items-baseline justify-between gap-3 tabular-nums"
          >
            <span>{labels?.used?.(percent!) ?? `${percent}% used`}</span>
            <span className="text-muted-foreground">
              {formatTokens(total)} / {formatTokens(windowTokens)}
            </span>
          </p>
          <ContextBar rows={rows} windowTokens={windowTokens} />
          <dl
            data-slot="context-panel-parts"
            className="grid grid-cols-[auto_minmax(0,1fr)_auto_auto] items-center gap-x-2.5 gap-y-1 text-xs"
          >
            {rows.map((row, index) => (
              <React.Fragment key={row.id}>
                <span
                  aria-hidden
                  className={cn(
                    "size-1.5 rounded-mark",
                    SWATCHES[index % SWATCHES.length],
                  )}
                />
                <dt className="min-w-0 truncate text-muted-foreground">
                  {row.label}
                </dt>
                <dd className="text-end tabular-nums">
                  {formatTokens(row.tokens)}
                </dd>
                <dd className="min-w-10 text-end text-muted-foreground tabular-nums">
                  {share(row.tokens, windowTokens)}
                </dd>
              </React.Fragment>
            ))}
            <span
              aria-hidden
              className="size-1.5 rounded-mark border border-muted-foreground/50"
            />
            <dt className="min-w-0 truncate text-muted-foreground">
              {labels?.free ?? "Left"}
            </dt>
            <dd className="text-end tabular-nums">{formatTokens(free)}</dd>
            <dd className="min-w-10 text-end text-muted-foreground tabular-nums">
              {share(free, windowTokens)}
            </dd>
          </dl>
        </>
      ) : (
        <p className="text-xs text-muted-foreground">
          {labels?.empty ?? "Measured after the first answer."}
        </p>
      )}
      <p
        data-slot="context-panel-threshold"
        className="text-xs text-muted-foreground"
      >
        {note}
      </p>
      {onSummarize ? (
        <Button
          variant="secondary"
          size="sm"
          data-slot="context-panel-summarize"
          aria-busy={busy || undefined}
          disabled={busy || !measured}
          onClick={summarize}
          className="self-end"
        >
          {/* The bolt loader is the one moving thing (no icon spinner). */}
          {busy ? <TextSpinner label="" /> : null}
          {busy
            ? (labels?.summarizing ?? "Starting")
            : (labels?.summarize ?? "Continue in a new chat")}
        </Button>
      ) : null}
    </div>
  );
}

/** The one segmented bar: each part's share of the window, in order, on the muted track. */
function ContextBar({
  rows,
  windowTokens,
}: {
  rows: readonly { id: string; tokens: number }[];
  windowTokens: number;
}) {
  return (
    <span
      aria-hidden
      data-slot="context-panel-bar"
      className="flex h-1.5 w-full gap-px overflow-hidden rounded-full bg-muted"
    >
      {rows.map((row, index) =>
        row.tokens > 0 ? (
          <span
            key={row.id}
            className={cn(
              "block h-full shrink-0",
              SWATCHES[index % SWATCHES.length],
            )}
            style={{ width: `${(row.tokens / windowTokens) * 100}%` }}
          />
        ) : null,
      )}
    </span>
  );
}
